const { execFileSync } = require('child_process');
const items = $input.all();

const DATE_RE  = /\d{1,4}[/.\-]\d{1,2}[/.\-]\d{1,4}/;
const PRICE_RE = /\d+[.,]\d{1,2}/g;
const TOTAL_KW = ['الإجمالي','الاجمالي','الإجمالى','الاجمالى','المجموع','الصافي','الصافى'];
const GENERIC  = ['إيصال','فاتورة','سند','receipt','invoice'];

const out = [];
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  const name = (bin && bin.fileName) ? bin.fileName : ('receipt-' + (i + 1));
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let text = '';
  try {
    text = execFileSync('tesseract', ['stdin', 'stdout', '-l', 'ara+eng', '--psm', '6'],
      { input: buf, encoding: 'utf8', maxBuffer: 20 * 1024 * 1024, stdio: ['pipe', 'pipe', 'ignore'] });
  } catch (e) { text = ''; }

  const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  const shop = lines.length ? lines[0] : '';
  const shopFound = !!shop && !GENERIC.some(g => shop.includes(g));
  const dm = text.match(DATE_RE);
  const date = dm ? dm[0] : '';
  let cands = [];
  for (const ln of lines) {
    if (TOTAL_KW.some(k => ln.includes(k))) {
      for (const n of (ln.match(PRICE_RE) || [])) cands.push(parseFloat(n.replace(',', '.')));
    }
  }
  const total = cands.length ? Math.max.apply(null, cands) : null;

  const missing = [];
  if (!shopFound) missing.push('اسم المتجر');
  if (!date)      missing.push('التاريخ');
  if (total === null) missing.push('الإجمالي');
  const status = missing.length ? 'مراجعة' : 'تم';

  out.push({ json: {
    'الملف': name,
    'المتجر': shop,
    'التاريخ': date,
    'الإجمالي': total,
    'الحالة': status,
    'ملاحظة': missing.length ? ('يحتاج تدقيق: ' + missing.join('، ')) : '',
    'النص_المقروء': text.replace(/\s+/g, ' ').trim().slice(0, 80),
  } });
}
return out;

const XLSX = require('@e965/xlsx');
const rows = $input.all().map(i => i.json);

const header = ['الملف', 'المتجر', 'التاريخ', 'الإجمالي', 'الحالة', 'ملاحظة'];
const dataAoa = [header];
let done = 0, review = 0, sum = 0;
for (const r of rows) {
  dataAoa.push([r['الملف'], r['المتجر'], r['التاريخ'], r['الإجمالي'], r['الحالة'], r['ملاحظة']]);
  if (r['الحالة'] === 'تم') done++; else review++;
  if (typeof r['الإجمالي'] === 'number') sum += r['الإجمالي'];
}

const sumAoa = [];
sumAoa.push(['ملخص قراءة الإيصالات (SAMPLE DATA)']);
sumAoa.push([]);
sumAoa.push(['عدد الإيصالات', rows.length]);
sumAoa.push(['مكتملة (تم)', done]);
sumAoa.push(['بحاجة لمراجعة', review]);
sumAoa.push(['مجموع الإجماليات المقروءة', Math.round(sum * 100) / 100]);

const wb = XLSX.utils.book_new();
XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(dataAoa), 'الإيصالات');
XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(sumAoa), 'الملخص');
const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
const bin = await this.helpers.prepareBinaryData(Buffer.from(buf), 'receipts.xlsx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
return [{ json: { receipts: rows.length, done: done, review: review,
  sum_total: Math.round(sum * 100) / 100 }, binary: { data: bin } }];
